class Solution:
    def countGoodIntegers(self, l: int, r: int, k: int) -> int:
        def f(x):
            s = str(x)
            n = len(s)
            from functools import lru_cache
            @lru_cache(maxsize=None)
            def dp(i, prev, tight, started):
                if i == n:
                    return 1 if started else 0
                res = 0
                lim = int(s[i]) if tight else 9
                for d in range(lim + 1):
                    nt = tight and d == lim
                    if started:
                        if abs(d - prev) > k:
                            continue
                        res += dp(i + 1, d, nt, True)
                    else:
                        res += dp(i + 1, d, nt, d != 0)
                return res
            return dp(0, 0, True, False)
        return f(r) - f(l - 1)

