class Solution {
public:
    long long countGoodIntegers(long long l, long long r, int k) {
        auto f = [&](long long x) -> long long {
            string s = to_string(x);
            int n = s.size();
            static int K;
            K = k;
            long long memo[17][11][2][2];
            memset(memo, -1, sizeof(memo));
            function<long long(int,int,bool,bool)> dp = [&](int i, int prev, bool tight, bool started) -> long long {
                if (i == n) return started ? 1 : 0;
                long long &res = memo[i][prev][tight][started];
                if (res != -1) return res;
                res = 0;
                int lim = tight ? s[i] - '0' : 9;
                for (int d = 0; d <= lim; d++) {
                    bool nt = tight && d == lim;
                    if (started) {
                        if (abs(d - prev) > K) continue;
                        res += dp(i + 1, d, nt, true);
                    } else {
                        res += dp(i + 1, d, nt, d != 0);
                    }
                }
                return res;
            };
            return dp(0, 0, true, false);
        };
        return f(r) - f(l - 1);
    }
};

