class Solution {
    private int k;
    private String s;
    private Long[][][][] memo;

    public long countGoodIntegers(long l, long r, int k) {
        this.k = k;
        return f(r) - f(l - 1);
    }

    private long f(long x) {
        s = Long.toString(x);
        int n = s.length();
        memo = new Long[n + 1][11][2][2];
        return dp(0, 0, true, false);
    }

    private long dp(int i, int prev, boolean tight, boolean started) {
        if (i == s.length()) return started ? 1 : 0;
        if (memo[i][prev][tight ? 1 : 0][started ? 1 : 0] != null)
            return memo[i][prev][tight ? 1 : 0][started ? 1 : 0];
        long res = 0;
        int lim = tight ? s.charAt(i) - '0' : 9;
        for (int d = 0; d <= lim; d++) {
            boolean nt = tight && d == lim;
            if (started) {
                if (Math.abs(d - prev) > k) continue;
                res += dp(i + 1, d, nt, true);
            } else {
                res += dp(i + 1, d, nt, d != 0);
            }
        }
        memo[i][prev][tight ? 1 : 0][started ? 1 : 0] = res;
        return res;
    }
}

