var countGoodIntegers = function(l, r, k) {
    const f = (x) => {
        const s = String(x);
        const n = s.length;
        const memo = new Map();
        const dp = (i, prev, tight, started) => {
            if (i === n) return started ? 1 : 0;
            const key = i * 10000 + prev * 100 + (tight ? 10 : 0) + (started ? 1 : 0);
            if (memo.has(key)) return memo.get(key);
            let res = 0;
            const lim = tight ? s.charCodeAt(i) - 48 : 9;
            for (let d = 0; d <= lim; d++) {
                const nt = tight && d === lim;
                if (started) {
                    if (Math.abs(d - prev) > k) continue;
                    res += dp(i + 1, d, nt, true);
                } else {
                    res += dp(i + 1, d, nt, d !== 0);
                }
            }
            memo.set(key, res);
            return res;
        };
        return dp(0, 0, true, false);
    };
    return f(r) - f(l - 1);
};
